from fastapi import FastAPI
app = FastAPI()
@app.post("/orders")
def create_order():
    return {"handler": "create_order"}
@app.get("/orders/current")
def current_order():
    return {"handler": "current_order"}
@app.get("/orders/{order_id}")
def retrieve_order():
    return {"handler": "retrieve_order"}
@app.put("/orders/{order_id}")
def replace_order():
    return {"handler": "replace_order"}
@app.delete("/orders/{order_id}")
def remove_order():
    return {"handler": "remove_order"}
